"use client"

import * as React from "react"

import {
  type BBox,
  type ConfidenceLevel,
  type FileRef,
  type FormField,
  type PageGroup,
  type PrimitiveError,
  type PrimitiveStatus,
  type ViewerAdapter,
  confidenceLevel,
  hueForIndex,
  pageCountFromGroups,
  toPageGroups,
} from "@/lib/retab"

// ---------------------------------------------------------------------------
// useViewerState — the shared status/error/empty state machine
// ---------------------------------------------------------------------------

export type ViewerPhase = "loading" | "ready" | "failed" | "empty"

export function useViewerState({
  status,
  error,
  hasOutput,
}: {
  status: PrimitiveStatus
  error?: PrimitiveError | null
  hasOutput: boolean
}): { phase: ViewerPhase } {
  const phase = React.useMemo<ViewerPhase>(() => {
    if (status === "failed" || error) return "failed"
    if (status === "completed") return hasOutput ? "ready" : "empty"
    return "loading"
  }, [status, error, hasOutput])
  return { phase }
}

// ---------------------------------------------------------------------------
// usePageRanges — normalize partition/split output into colorable page groups
// ---------------------------------------------------------------------------

export interface PageRangesModel {
  groups: PageGroup[]
  pageCount: number
  /** 1-based page -> indexes of groups that contain it (handles overlap). */
  pageOwners: Map<number, number[]>
  hueFor: (index: number) => number
}

export function usePageRanges(
  output:
    | { key: string; pages: number[] }[]
    | { name: string; pages: number[] }[]
    | PageGroup[]
    | null
    | undefined,
  pageCount?: number
): PageRangesModel {
  return React.useMemo(() => {
    const groups = isPageGroups(output) ? output : toPageGroups(output ?? [])
    const total = pageCount ?? pageCountFromGroups(groups)
    const pageOwners = new Map<number, number[]>()
    groups.forEach((g) => {
      g.pages.forEach((p) => {
        const owners = pageOwners.get(p) ?? []
        owners.push(g.index)
        pageOwners.set(p, owners)
      })
    })
    return { groups, pageCount: total, pageOwners, hueFor: hueForIndex }
  }, [output, pageCount])
}

function isPageGroups(value: unknown): value is PageGroup[] {
  return (
    Array.isArray(value) &&
    value.length > 0 &&
    typeof (value[0] as PageGroup).label === "string" &&
    typeof (value[0] as PageGroup).index === "number"
  )
}

// ---------------------------------------------------------------------------
// useBBoxOverlay — map normalized bboxes to CSS rectangles for one page
// ---------------------------------------------------------------------------

export interface OverlayRect {
  field: FormField
  /** Percentage-based style for an absolutely-positioned box. */
  style: React.CSSProperties
}

export function useBBoxOverlay(
  fields: FormField[] | undefined,
  page: number
): OverlayRect[] {
  return React.useMemo(() => {
    return (fields ?? [])
      .filter((f) => f.bbox.page === page)
      .map((field) => ({
        field,
        style: rectStyle(field.bbox),
      }))
  }, [fields, page])
}

export function rectStyle(bbox: BBox): React.CSSProperties {
  return {
    position: "absolute",
    left: `${bbox.left * 100}%`,
    top: `${bbox.top * 100}%`,
    width: `${bbox.width * 100}%`,
    height: `${bbox.height * 100}%`,
  }
}

// ---------------------------------------------------------------------------
// useConsensusLikelihood — turn raw likelihoods into confidence + buckets
// ---------------------------------------------------------------------------

export interface Confidence {
  value: number | null
  level: ConfidenceLevel | null
}

export function useConsensusLikelihood(
  likelihoods: (number | null | undefined)[] | undefined
): Confidence[] {
  return React.useMemo(
    () =>
      (likelihoods ?? []).map((value) => ({
        value: value ?? null,
        level: confidenceLevel(value),
      })),
    [likelihoods]
  )
}

/** Average a per-page likelihood array into a single page-group confidence. */
export function meanLikelihood(pages: number[] | undefined): number | null {
  if (!pages || pages.length === 0) return null
  return pages.reduce((a, b) => a + b, 0) / pages.length
}

// ---------------------------------------------------------------------------
// useDocumentUrl — resolve a FileRef through the adapter (async)
// ---------------------------------------------------------------------------

export interface AsyncResource<T> {
  data: T | null
  loading: boolean
  error: Error | null
}

export function useDocumentUrl(
  adapter: ViewerAdapter | undefined,
  file: FileRef | undefined
): AsyncResource<string> {
  const [state, setState] = React.useState<AsyncResource<string>>({
    data: null,
    loading: false,
    error: null,
  })

  React.useEffect(() => {
    if (!adapter?.getDocumentUrl || !file) {
      setState({ data: null, loading: false, error: null })
      return
    }
    let cancelled = false
    setState({ data: null, loading: true, error: null })
    Promise.resolve(adapter.getDocumentUrl(file))
      .then((url) => {
        if (!cancelled) setState({ data: url, loading: false, error: null })
      })
      .catch((error: unknown) => {
        if (!cancelled)
          setState({
            data: null,
            loading: false,
            error: error instanceof Error ? error : new Error(String(error)),
          })
      })
    return () => {
      cancelled = true
    }
    // adapter identity is the consumer's responsibility to keep stable
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [adapter, file?.id])

  return state
}

// ---------------------------------------------------------------------------
// useExtractionSources — lazily fetch field-level grounding via the adapter
// ---------------------------------------------------------------------------

export function useExtractionSources(
  adapter: ViewerAdapter | undefined,
  extractionId: string | undefined,
  enabled = true
) {
  const [state, setState] = React.useState<
    AsyncResource<Awaited<ReturnType<NonNullable<ViewerAdapter["getExtractionSources"]>>>>
  >({ data: null, loading: false, error: null })

  React.useEffect(() => {
    if (!enabled || !adapter?.getExtractionSources || !extractionId) {
      return
    }
    let cancelled = false
    setState({ data: null, loading: true, error: null })
    adapter
      .getExtractionSources(extractionId)
      .then((data) => {
        if (!cancelled) setState({ data, loading: false, error: null })
      })
      .catch((error: unknown) => {
        if (!cancelled)
          setState({
            data: null,
            loading: false,
            error: error instanceof Error ? error : new Error(String(error)),
          })
      })
    return () => {
      cancelled = true
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [adapter, extractionId, enabled])

  return state
}
